class Solution:
    def minimizeError(self, prices: List[str], target: int) -> str:
        INF = float('inf')
        fracs = []
        floor_sum = 0
        for p in prices:
            v = round(float(p) * 1000)
            floor_sum += v // 1000
            fracs.append(v % 1000)
        ceil_sum = floor_sum + sum(1 for f in fracs if f > 0)
        if target < floor_sum or target > ceil_sum:
            return "-1"
        dp = [INF] * (len(prices) + 1)
        dp[0] = 0
        for f in fracs:
            ndp = [INF] * (len(prices) + 1)
            for j in range(len(prices) + 1):
                if dp[j] == INF:
                    continue
                ndp[j] = min(ndp[j], dp[j] + f)
                if j + 1 <= len(prices):
                    ndp[j + 1] = min(ndp[j + 1], dp[j] + 1000 - f)
            dp = ndp
        err = dp[target - floor_sum]
        return "%d.%03d" % (err // 1000, err % 1000)

