class Solution {
public:
    string minimizeError(vector<string>& prices, int target) {
        long long floorSum = 0;
        vector<int> fracs;
        for (auto& p : prices) {
            long long v = llround(stod(p) * 1000);
            floorSum += v / 1000;
            fracs.push_back(v % 1000);
        }
        long long ceilSum = floorSum;
        for (int f : fracs) if (f > 0) ceilSum++;
        if (target < floorSum || target > ceilSum) return "-1";
        int n = fracs.size();
        vector<long long> dp(n + 1, LLONG_MAX / 2), ndp(n + 1);
        dp[0] = 0;
        for (int f : fracs) {
            fill(ndp.begin(), ndp.end(), LLONG_MAX / 2);
            for (int j = 0; j <= n; j++) {
                if (dp[j] >= LLONG_MAX / 2) continue;
                ndp[j] = min(ndp[j], dp[j] + f);
                if (j + 1 <= n) ndp[j + 1] = min(ndp[j + 1], dp[j] + 1000 - f);
            }
            swap(dp, ndp);
        }
        long long err = dp[target - floorSum];
        char buf[16];
        snprintf(buf, sizeof(buf), "%lld.%03lld", err / 1000, err % 1000);
        return string(buf);
    }
};

