        long floorSum = 0;
        List<Integer> fracs = new ArrayList<>();
        for (String p : prices) {
            long v = Math.round(Double.parseDouble(p) * 1000);
            floorSum += v / 1000;
            fracs.add((int)(v % 1000));
        }
        long ceilSum = floorSum;
        for (int f : fracs) if (f > 0) ceilSum++;
        if (target < floorSum || target > ceilSum) return "-1";
        int n = fracs.size();
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;
        for (int f : fracs) {
            long[] ndp = new long[n + 1];
            Arrays.fill(ndp, Long.MAX_VALUE / 2);
            for (int j = 0; j <= n; j++) {
                if (dp[j] >= Long.MAX_VALUE / 2) continue;
                ndp[j] = Math.min(ndp[j], dp[j] + f);
                if (j + 1 <= n) ndp[j + 1] = Math.min(ndp[j + 1], dp[j] + 1000 - f);
            }
            dp = ndp;
        }
        long err = dp[target - floorSum];
        return String.format("%d.%03d", err / 1000, err % 1000);
    }
}

